<div class="form-grid"><x-field name="name" label="Full name" :value="$record->name" :required="true" maxlength="100"/><x-field name="email" label="Login email" type="email" :value="$record->email" :required="true" maxlength="190" autocomplete="off"/><x-field name="password" label="Temporary password" type="password" :required="!$record->exists" minlength="12" maxlength="128" autocomplete="new-password" help="At least 12 characters, upper/lowercase, and a number. Leave blank on edit to keep the password. Share privately."/><x-field name="role" label="Role" type="select" :value="$record->role" :options="['learner'=>'Learner','super_admin'=>'Super administrator']" :required="true"/></div>
<x-toggle name="is_active" label="Active account" :value="$record->is_active" help="Inactive accounts cannot sign in. Account changes require existing sessions to sign in again."/>
<div class="form-section-label">A personal learning experience</div>
<div class="form-grid"><x-field name="theme_mode" label="Theme behavior" type="select" :value="$record->theme_mode" :options="['random_login'=>'Random theme at each login','fixed'=>'Always use the assigned theme']"/><x-field name="theme_id" label="Assigned theme" type="select" :value="$record->theme_id" :options="[''=>'Select a fixed theme']+$themes->pluck('name','id')->all()" help="Required only when theme behavior is fixed."/></div>
<x-field name="theme_ids[]" label="Allowed random themes" type="select" :multiple="true" :value="$record->exists ? $record->themes->pluck('id')->all() : []" :options="$themes->mapWithKeys(fn($t)=>[$t->id=>$t->name.' / '.ucfirst($t->layout)])->all()" size="6" help="Leave empty to allow all active themes. A random theme stays stable for the session; consecutive repeats are avoided when possible."/>
<div class="notice">Learners must replace a new or reset temporary password at their next sign-in. There is no public registration.</div>
